/**
 * The web portal builds the Veritag domain binding byte-identically to the
 * Python backend (veritag-core arttrust/binding.py) and the Dart portal, so a tag
 * minted from the web matches one minted from mobile. Expected values are
 * generated by binding.py.
 */
import test from "node:test";
import assert from "node:assert/strict";

import { veritagBinding, verdictOf } from "../dist/portal.js";

const toHex = (u8) => [...u8].map((b) => b.toString(16).padStart(2, "0")).join("");

const VECTORS = [
  {
    uid: "04D2760000850100",
    title: "Composition VIII",
    artistId: "artist_0042",
    hex: "b958f7c3cc046a676532abc14aeb0744a394da8c93036bc6950eb010ae1d2600",
  },
  {
    uid: "AABBCCDDEEFF0011",
    title: "Café Terrace",
    artistId: "artist_0099",
    hex: "27aa7e6819afbc4459a3bdcc888f7d9662e2512058f5ff423165de23536e52ac",
  },
];

test("veritagBinding matches the Python backend", async () => {
  for (const v of VECTORS) {
    assert.equal(toHex(await veritagBinding(v.uid, v.title, v.artistId)), v.hex);
  }
});

test("verdict policy maps the three booleans", () => {
  const base = { issuer_id: null, reason: "" };
  assert.equal(verdictOf({ ...base, chip_authentic: false, not_replayed: false, issuer_verified: false }), "counterfeit");
  assert.equal(verdictOf({ ...base, chip_authentic: true, not_replayed: false, issuer_verified: false }), "replayed");
  assert.equal(verdictOf({ ...base, chip_authentic: true, not_replayed: true, issuer_verified: false }), "unverified_artist");
  assert.equal(verdictOf({ ...base, chip_authentic: true, not_replayed: true, issuer_verified: true }), "authentic");
});

test("parseTap reads every shape a tag or a share can hand us", async () => {
  const { parseTap } = await import("../dist/portal.js");
  assert.deepEqual(parseTap("https://app.veritag.art/p?u=04a1b2c3d4e501&c=7&m=abcdef0123456789&kv=1"), {
    u: "04A1B2C3D4E501", c: 7, m: "abcdef0123456789", kv: 1,
  });
  assert.deepEqual(parseTap("app.veritag.art/t/04a1b2c3d4e501"), { uid: "04A1B2C3D4E501" });
  assert.deepEqual(parseTap("04a1b2c3d4e501"), { uid: "04A1B2C3D4E501" });
  // the NDEF payload itself: the counter mirror is hex
  assert.deepEqual(parseTap("v1;u=04A1B2C3D4E501;c=00000A;m=ABCDEF0123456789"), {
    u: "04A1B2C3D4E501", c: 10, m: "abcdef0123456789", kv: 1,
  });
  assert.equal(parseTap(""), null);
  assert.equal(parseTap("https://example.com/hello"), null);
  assert.equal(parseTap("not a tag"), null);
});
